import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';

export default function Resources() {
  const { selectedCollege, dark, user } = useApp();

  const [data, setData] = useState([]);

  // 🔥 FETCH DATA
  const fetchResources = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/resources");
      const result = await res.json();

      if (Array.isArray(result)) {
        setData(result);
      } else {
        setData([]);
      }
    } catch (err) {
      console.error(err);
      setData([]);
    }
  };

  useEffect(() => {
    fetchResources();
  }, []);

  const displayCollege =
    user?.role === 'student' && user?.college
      ? user.college
      : selectedCollege;

  // 🔥 DELETE
  const handleDelete = async (id) => {
    if (!window.confirm("Delete this resource?")) return;

    try {
      const token = localStorage.getItem('token');

      const res = await fetch(`http://localhost:5000/api/resources/${id}`, {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${token}`
        }
      });

      if (res.ok) {
        alert("Deleted successfully");
        fetchResources(); // refresh
      } else {
        const err = await res.json();
        alert("Delete failed: " + err.message);
      }

    } catch (err) {
      console.error(err);
      alert("Error deleting");
    }
  };

  return (
    <div className="fade-in">
      <h1>{displayCollege ? displayCollege.short : 'All'} Resources</h1>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12 }}>
        {Array.isArray(data) && data.map((r) => (
          <div
            key={r._id}
            style={{
              width: '320px',
              padding: 10,
              border: '1px solid #ccc',
              borderRadius: 10,
              background: dark ? '#1e293b' : '#fff'
            }}
          >
            <h3 style={{ fontSize: 15 }}>{r.title}</h3>

            <p style={{ fontSize: 13 }}>
              {r.subject} · {r.uploadedBy?.name || r.uploadedBy}
            </p>

            <p style={{ fontSize: 13 }}>
              {r.college?.name || r.college}
            </p>

            {/* 🔥 PREVIEW FIX */}
            {r.fileUrl && (
              <div>
                {r.fileUrl.endsWith('.pdf') ? (
                  <iframe
                    src={`http://localhost:5000${r.fileUrl}`}
                    width="100%"
                    height="200px"
                    title="PDF"
                  />
                ) : (
                  <div
                    style={{
                      height: 200,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      background: '#eee',
                      color: '#333',
                      borderRadius: 6
                    }}
                  >
                    No preview available
                  </div>
                )}
              </div>
            )}

            {/* 🔥 BUTTONS */}
            <div style={{ display: 'flex', gap: 6, marginTop: 8 }}>

              {/* OPEN */}
              {r.fileUrl && (
                <button
                  onClick={() => window.open(`http://localhost:5000${r.fileUrl}`)}
                  style={{
                    fontSize: 12,
                    padding: '4px 8px',
                    cursor: 'pointer'
                  }}
                >
                  Open
                </button>
              )}

              {/* DELETE */}
              {user?.role === 'teacher' && (
                <button
                  onClick={() => handleDelete(r._id)}
                  style={{
                    fontSize: 12,
                    padding: '4px 8px',
                    background: 'red',
                    color: '#fff',
                    border: 'none',
                    borderRadius: 4,
                    cursor: 'pointer'
                  }}
                >
                  Delete
                </button>
              )}

            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
